import pytest

from minisheet.refs import Ref, parse_ref, parse_range, to_a1


# B§1 table rows
def test_parse_ref_b12():
    assert parse_ref("B12") == Ref(1, 11, False, False)


def test_parse_ref_absolute_zz_9999():
    assert parse_ref("$zz$9999") == Ref(701, 9998, True, True)


def test_parse_range_mixed_flags_normalized():
    assert parse_range("$C3:A$1") == (
        Ref(0, 0, False, True),
        Ref(2, 2, True, False),
    )


def test_to_a1_absolute_col():
    assert to_a1(Ref(26, 0, True, False)) == "$AA1"


def test_parse_ref_a0_rejected():
    with pytest.raises(ValueError):
        parse_ref("A0")


def test_parse_ref_aaa1_rejected():
    with pytest.raises(ValueError):
        parse_ref("AAA1")


# Spec-stated rules
def test_parse_ref_a10000_rejected():
    with pytest.raises(ValueError):
        parse_ref("A10000")


def test_parse_ref_a9999_accepted():
    assert parse_ref("A9999") == Ref(0, 9998)


def test_parse_ref_column_bounds():
    assert parse_ref("A1") == Ref(0, 0)
    assert parse_ref("Z1") == Ref(25, 0)
    assert parse_ref("AA1") == Ref(26, 0)
    assert parse_ref("ZZ1") == Ref(701, 0)


def test_parse_ref_lowercase_accepted():
    assert parse_ref("b12") == Ref(1, 11)


def test_parse_ref_dollar_flags():
    assert parse_ref("$A1") == Ref(0, 0, True, False)
    assert parse_ref("A$1") == Ref(0, 0, False, True)


def test_parse_ref_whitespace_rejected():
    with pytest.raises(ValueError):
        parse_ref(" A1")
    with pytest.raises(ValueError):
        parse_ref("A1 ")


def test_parse_ref_leading_zero_row_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


# Review Focus
def test_a01_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


def test_range_bare_cell():
    with pytest.raises(ValueError):
        parse_range("A1")


def test_to_a1_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(702, 0))


