    # Rows: min row is 1 (from A1, no flag) and max row is 3 (from $A$3).
    assert parse_range("A1:$A$3") == (Ref(0, 0), Ref(0, 2, True, True))


def test_parse_range_bad_side_rejected():
    with pytest.raises(ValueError):
        parse_range("A1:A0")


def test_parse_range_three_parts_rejected():
    with pytest.raises(ValueError):
        parse_range("A1:B2:C3")


def test_to_a1_plain():
    assert to_a1(Ref(0, 0)) == "A1"
    assert to_a1(Ref(701, 9998)) == "ZZ9999"


def test_to_a1_both_flags():
    assert to_a1(Ref(1, 11, True, True)) == "$B$12"


def test_to_a1_negative_col_rejected():
    with pytest.raises(ValueError):
        to_a1(Ref(-1, 0))


def test_to_a1_row_past_max_rejected():
    with pytest.raises(ValueError):
        to_a1(Ref(0, 9999))


def test_roundtrip_to_a1_parse_ref():
    for ref in (Ref(0, 0), Ref(25, 9), Ref(26, 99), Ref(701, 9998, True, False)):
        assert parse_ref(to_a1(ref)) == ref

