from __future__ import annotations

import re
from dataclasses import dataclass


@dataclass(frozen=True)
class Ref:
    col: int
    row: int
    abs_col: bool = False
    abs_row: bool = False

__all__ = ["parse_ref", "parse_range", "to_a1"]

_REF_RE = re.compile(r"(\$?)([A-Za-z]{1,2})(\$?)([1-9][0-9]{0,3})")
_MAX_COL = 701  # ZZ
_MAX_ROW = 9998  # row 9999, 0-based


def _col_index(letters: str) -> int:
    letters = letters.upper()
    if len(letters) == 1:
        return ord(letters) - ord("A")
    return (ord(letters[0]) - ord("A") + 1) * 26 + (ord(letters[1]) - ord("A"))


def _col_letters(col: int) -> str:
    if col < 26:
        return chr(ord("A") + col)
    return chr(ord("A") + col // 26 - 1) + chr(ord("A") + col % 26)


def parse_ref(s: str) -> Ref:
    m = _REF_RE.fullmatch(s)
    if m is None:
        raise ValueError(f"invalid cell reference: {s!r}")
    return Ref(
        _col_index(m.group(2)),
        int(m.group(4)) - 1,
        m.group(1) == "$",
        m.group(3) == "$",
    )


def parse_range(s: str) -> tuple[Ref, Ref]:
    parts = s.split(":")
    if len(parts) != 2:
        raise ValueError(f"invalid range: {s!r}")
    a = parse_ref(parts[0])
    b = parse_ref(parts[1])
    # Each axis: the corner supplying min/max gives its flag; on a tie the first corner.
    if a.col == b.col:
        col_lo = col_hi = a
    else:
        col_lo, col_hi = (a, b) if a.col < b.col else (b, a)
    if a.row == b.row:
        row_lo = row_hi = a
    else:
        row_lo, row_hi = (a, b) if a.row < b.row else (b, a)
    top_left = Ref(col_lo.col, row_lo.row, col_lo.abs_col, row_lo.abs_row)
    bottom_right = Ref(col_hi.col, row_hi.row, col_hi.abs_col, row_hi.abs_row)
    return top_left, bottom_right


def to_a1(ref: Ref) -> str:
    if not (0 <= ref.col <= _MAX_COL and 0 <= ref.row <= _MAX_ROW):
        raise ValueError(f"cell out of range: {ref!r}")
    return (
        ("$" if ref.abs_col else "")
        + _col_letters(ref.col)
        + ("$" if ref.abs_row else "")
        + str(ref.row + 1)
    )

